--- 回收全部节点 grid（逆序，复用 PBR RoundPanel 范式）。
function XUiPunishaarFightMainCommonFightMain:RecycleAllStageGrids()
    if XTool.IsTableEmpty(self._StageGridList) then return end
    for i = #self._StageGridList, 1, -1 do
