end

--- 刷新节点进度：文本"当前/总数" + 按总节点数刷出 grid 列表（三态见 GridStage.Refresh）。
function XUiPunishaarFightMainCommonFightMain:RefreshStageProgress()
    local stageId = self._Control:GetCurrentStageId()
    if not stageId then return end

    local total = self._Control:GetStageTotalNodeCount(stageId) or 0
    local curIndex = self._Control:GetCurrentNodeIndex() or 0

    if self.TxtRoundNum then
        self.TxtRoundNum.text = string.format("%d/%d", curIndex, total)
    end

    self:RecycleAllStageGrids()

    for i = 1, total do
        local grid = self._StageGridPool:GetItemFromPool()
        grid:Open()
        grid:Refresh(stageId, i, curIndex, total)
        table.insert(self._StageGridList, grid)
    end

    -- 列表布局重建（对齐 PBR RefreshWavesShow）
    if self.ListStage and self.ListStage.content then
        CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.ListStage.content)
    end
    -- 聚焦当前节点（居中），对齐 PBR RoundPanel.FocusCurWaveUI
    self:FocusCurNodeUI(curIndex, false)
end

