--- 聚焦指定节点到视口中心（复用通用组件 XUiPBRStageListScrollView.PlayScrollViewMove）。
---@param index number 节点序号（1-based）
---@param onlyViewFull boolean true=只要完全显示即可；false=居中
---@param cb function|nil 移动完成回调
function XUiPunishaarFightMainCommonFightMain:FocusCurNodeUI(index, onlyViewFull, cb)
    local grid = self._StageGridList[index]
    if not grid or not self._ScrollViewMove then return end

    local halfView = self._ScrollViewMove.HalfViewPortWidth
    local content = self.ListStage.content
    local gridLocalX = grid.Transform.localPosition.x
    local tarPosX

    if onlyViewFull then
        -- 让目标 grid 完全显示在视口内（左右边界 Clamp）
        local halfGrid = grid.Transform.sizeDelta.x / 2
        -- TODO: 边界留白 offset 若需可后续接 ClientConfig，暂用 0
        local leftPos = -halfView - gridLocalX + halfGrid
        local rightPos = halfView - gridLocalX - halfGrid
        tarPosX = XMath.Clamp(content.localPosition.x, leftPos, rightPos)
    else
        -- 聚焦到视口中心（content 锚点在左侧，0=起始）
        tarPosX = -gridLocalX
    end

    -- 越界夹取：不可大于 0（起始），不可小于 -(content 宽 - 半视口)
    local maxLeft = -content.sizeDelta.x + halfView
    tarPosX = XMath.Clamp(tarPosX, maxLeft, -halfView)

    self._ScrollViewMove:PlayScrollViewMove(tarPosX, nil, true, cb)
end

--endregion

function XUiPunishaarFightMainCommonFightMain:SetShowOnFighting()
    self.PanelAsset:Close()
    -- PanelTop 是关卡进度容器（TxtRoundNum+ListStage+装饰 UI 的父节点），整容器隐以一并遮蔽全部进度内容。
    -- 隐前先 Close 内部实例化 XUiNode（pool grids）：避免 Open 态 XUiNode 挂 activeSelf=false 容器下，
    -- 否则 root 恢复时 EnableChildNodes 级联重 Enable 会触发 _CheckUIActive 报错（RecycleAllStageGrids 经池 onRelease 调 grid:Close）。
    self:RecycleAllStageGrids()
    if self.PanelTop then
        self.PanelTop.gameObject:SetActiveEx(false)
    end
    -- 倍速按钮仅战斗中显 + 同步数字 #50/#68
    if self.BtnSpeed then
        self.BtnSpeed.gameObject:SetActiveEx(true)
        self:_RefreshSpeedBtnState()
    end
    -- 自动战斗按钮仅当前关卡启用自动战斗（PunishaarStageGroup.EnableCardAutoMode）时显 + 同步选中态/AutoPlay 动画 #Auto
    if self.BtnAuto then
        local steControl = self:_GetSTEControl()
        local autoByStage = steControl and steControl:IsAutoModeEnabledByStage()
        self.BtnAuto.gameObject:SetActiveEx(autoByStage == true)
        self:_RefreshAutoBtnState()
    end
    -- VSNotify 期间两按钮先 Disable：须在两按钮 refresh 之后调用，Disable 后生效不被 refresh 覆盖
    -- （持久化偏好+驱动归 FightControl:InitNewGame）#50/#68/#Auto
    self:SetSpeedBtnInteractable(false)
    -- 飘字播放器：战斗 Open（触发 OnStart→建池）/ 非战斗 Close #飘字
    if self._DamageNumberPlayer then
        self._DamageNumberPlayer:Open()
    end
    -- 我方副卡槽刷新（Fighting 卡在板上，跟模型走应显；若 RoleModelUiShow 挂 PanelTop 下则随 PanelTop 隐，需 prefab 移出）#副卡槽联动
    if self.RoleModelUiShow then
        self.RoleModelUiShow:Refresh()
    end
end

