    if self.BtnSpeed then
        self.BtnSpeed.gameObject:SetActiveEx(false)
    end
    if self.BtnAuto then
        self.BtnAuto.gameObject:SetActiveEx(false)
        self:_RefreshAutoBtnState()  -- 停 AutoPlay 动画（按钮隐）#AutoPlay
    end
    -- 我方副卡槽初始刷新（暂离重进/直进 Shop 无 BuySuccess 时补刷；后续卡集合变更由订阅刷）#副卡槽联动
